"""Local go2rtc control; provider URLs never leave this process."""
from __future__ import annotations

import urllib.parse
import urllib.request
from urllib.error import HTTPError
import hashlib


class Go2Rtc:
    def __init__(self, api_url: str = 'http://127.0.0.1:1984'):
        self.api_url = api_url.rstrip('/')

    def replace_source(self, name: str, source: str) -> None:
        query = urllib.parse.urlencode({'name': name, 'src': source})
        try:
            request = urllib.request.Request(f'{self.api_url}/api/streams?{query}', method='PATCH')
            with urllib.request.urlopen(request, timeout=10): pass
        except HTTPError as exc:
            if exc.code != 404: raise
            request = urllib.request.Request(f'{self.api_url}/api/streams?{query}', method='PUT')
            with urllib.request.urlopen(request, timeout=10): pass

    @staticmethod
    def stable_name(checkpoint_id: str) -> str:
        digest=hashlib.sha256(checkpoint_id.encode()).hexdigest()[:12]
        return f'md_parking_{digest}'
